// Generates src/lib-bundle.ts — exports two constants the typecheck
// wasm consumes:
//
//   - TS_LIB_FILES      : the `lib.*.d.ts` files TypeScript asks for
//                         when resolving --lib entries (DOM excluded)
//   - PARTICLE_GLOBALS_DTS : the type declarations for the host-provided
//                         `particle:*` namespaces (loaded as a synthetic
//                         root file by typecheck.ts)
//
// Why not import lib.*.d.ts at runtime? typescript ships them as plain
// .d.ts text on disk; doing it via glob would tie esbuild config into
// the build. A small generator script keeps the typecheck JS source
// uncluttered.
//
// Why drop lib.dom.d.ts? Particles run server-side — the QuickJS
// runtime ships fetch / Request / Response / Headers / URL /
// URLSearchParams / Blob / FormData / TextEncoder / etc. via
// wasm-rquickjs's web-platform polyfills. lib.webworker.d.ts is the
// closest TS-native description of that environment without the
// 600 KB of Window/Document/HTMLElement cruft DOM brings.
//
// Run from the typecheck component directory:
//   node build-lib-bundle.mjs
//
// Driven by the typecheck Makefile target.

import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const libDir = "node_modules/typescript/lib";

const files = readdirSync(libDir).filter((f) => {
  if (!f.startsWith("lib.") || !f.endsWith(".d.ts")) return false;
  // Particles aren't browsers; cut DOM. Keep webworker — that's
  // where Request/Response/Headers/URL/URLSearchParams/Blob live
  // in TypeScript's standard libs.
  if (f.includes("dom")) return false;
  return true;
});

const map = {};
let total = 0;
for (const f of files.sort()) {
  const data = readFileSync(join(libDir, f), "utf8");
  map[f] = data;
  total += data.length;
}

// The particle:* module declarations. Loaded as a synthetic root
// file by libBundleHost so user code can `import { credentials }
// from "particle:credentials"` without a separate types package.
const particleGlobals = readFileSync("src/particle-globals.d.ts", "utf8");

const out = `// Generated by build-lib-bundle.mjs. DO NOT EDIT.
//
// TS_LIB_FILES      : subset of TypeScript's bundled lib.*.d.ts
//                     files (DOM excluded). Backs the typecheck
//                     CompilerHost so lib resolution works without
//                     host filesystem access at runtime.
//
// PARTICLE_GLOBALS_DTS : type declarations for the host-provided
//                     particle:* namespaces (credentials, oauth,
//                     signing, kv). Injected as a synthetic root
//                     file in every typecheck program.
//
// eslint-disable
export const TS_LIB_FILES: Record<string, string> = ${JSON.stringify(map)};

export const PARTICLE_GLOBALS_DTS: string = ${JSON.stringify(particleGlobals)};
`;

mkdirSync("src", { recursive: true });
writeFileSync("src/lib-bundle.ts", out);

console.log(
  `wrote src/lib-bundle.ts: ${files.length} libs, ${(total / 1024).toFixed(0)} KB total`,
);
